import{_ as t,o,c as d,ag as i}from"./chunks/framework.DaCm-iTo.js";const p=JSON.parse('{"title":"Socketing Process","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/gem/process.md","filePath":"en/modules/gem/process.md","lastUpdated":null}'),s={name:"en/modules/gem/process.md"};function a(c,e,r,n,l,m){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="socketing-process" tabindex="-1">Socketing Process <a class="header-anchor" href="#socketing-process" aria-label="Permalink to &quot;Socketing Process&quot;">​</a></h1><p>The Gem process validates the equipment, socket item definition, gem item, socket state, and costs before writing gem data to the equipment and rebuilding its presentation.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li>The player opens the gem GUI or runs a gem command. Inlay, socket-opening, and upgrade GUIs open with an empty target slot; they do not clone or move equipment from the player&#39;s main hand or inventory automatically.</li><li>The module reads the target equipment and selects an <code>items/*.yml</code> socket item definition through its <code>match</code> rules.</li><li>It reads <code>slots</code> and filters slots that are not open, already occupied, or not valid for the current operation.</li><li>It loads the gem definition and checks whether gem <code>socket_compatibility</code> matches the target <code>slots[].type</code>.</li><li>It checks socket item limits such as <code>allowed_gem_types</code>, <code>max_same_type</code>, and <code>max_same_id</code>.</li><li>It checks conditions and costs, such as <code>inlay_cost</code>, <code>extract_cost</code>, socket openers, or upgrade materials.</li><li>It writes gem id, current level, slot index, and gem layer data to item PDC.</li><li>CoreLib&#39;s item operation ledger (<code>ItemOperationLedger</code>) rebuilds name, lore, attribute payload, and skill payload.</li><li>Gem resonances are re-evaluated, and resonance effects are applied or removed.</li><li>Actions run and the player&#39;s inventory is refreshed.</li></ol><h2 id="key-validation-fields" tabindex="-1">Key validation fields <a class="header-anchor" href="#key-validation-fields" aria-label="Permalink to &quot;Key validation fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Config location</th><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>items/*.yml</code></td><td><code>match.item_sources</code></td><td>Which items receive this socket definition.</td></tr><tr><td><code>items/*.yml</code></td><td><code>slots[].type</code></td><td>Socket type, such as <code>attack</code>, <code>defense</code>, or <code>universal</code>.</td></tr><tr><td><code>items/*.yml</code></td><td><code>default_open_slots</code></td><td>Socket indexes that are open by default. Other sockets require opening.</td></tr><tr><td><code>items/*.yml</code></td><td><code>allowed_gem_types</code></td><td>Gem type allowlist for this equipment.</td></tr><tr><td><code>items/*.yml</code></td><td><code>max_same_type</code></td><td>Maximum number of gems with the same type. Unlimited when not configured.</td></tr><tr><td><code>items/*.yml</code></td><td><code>max_same_id</code></td><td>Maximum number of gems with the same id.</td></tr><tr><td><code>gems/*.yml</code></td><td><code>gem_type</code></td><td>The gem&#39;s own type.</td></tr><tr><td><code>gems/*.yml</code></td><td><code>socket_compatibility</code></td><td>Socket types this gem can be inserted into.</td></tr><tr><td><code>gems/*.yml</code></td><td><code>inlay_cost</code> / <code>extract_cost</code></td><td>Inlay and extraction costs.</td></tr></tbody></table><blockquote><p>Older documentation may mention <code>slot_types</code>; the current source uses <code>socket_compatibility</code> together with <code>slots[].type</code>.</p></blockquote><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>Missing socket item definition: the equipment does not support gems.</li><li>Locked socket: the player must open it first with a socket opener.</li><li>Occupied socket: it cannot be overwritten outside extraction or replacement flows.</li><li>Stacked gem items: usually only one item is consumed.</li><li>Full inventory during extraction: returned gems should be inserted safely or dropped.</li><li>GUI open behavior: target equipment and materials must be placed manually by the player. The module does not auto-use the main-hand item as the initial target, preventing accidental item movement.</li><li>Config reloads that remove old gem ids: the item keeps stored ids when possible and falls back during presentation rebuild. Gem items are refreshed from current definitions when obtained, after reloads, and when reconstructed inside GUIs.</li></ul>',9)])])}const u=t(s,[["render",a]]);export{p as __pageData,u as default};
